import { HttpResponse, http } from 'msw';

import { env } from '@/config/env';

import { db, persistDb } from '../db';
import { requireAuth, networkDelay } from '../utils';

type TeamBody = {
  name: string;
  description: string;
};

const isNonEmptyString = (value: unknown): value is string =>
  typeof value === 'string' && value.trim().length > 0;

export const teamsHandlers = [
  http.get(`${env.API_URL}/teams`, async () => {
    await networkDelay();

    try {
      const result = db.team.getAll();
      return HttpResponse.json({ data: result });
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),

  http.post(`${env.API_URL}/teams`, async ({ request, cookies }) => {
    await networkDelay();

    try {
      const { user, error } = requireAuth(cookies);
      if (error) {
        return HttpResponse.json({ message: error }, { status: 401 });
      }
      if (user?.role !== 'ADMIN') {
        return HttpResponse.json(
          { message: 'Only admins can create teams' },
          { status: 403 },
        );
      }

      const data = (await request.json()) as Partial<TeamBody>;
      if (!isNonEmptyString(data?.name) || !isNonEmptyString(data?.description)) {
        return HttpResponse.json(
          { message: 'Name and description are required' },
          { status: 400 },
        );
      }

      // Pick the fields explicitly so the client cannot set id or createdAt.
      const result = db.team.create({
        name: data.name,
        description: data.description,
      });
      await persistDb('team');
      return HttpResponse.json(result);
    } catch (error: any) {
      return HttpResponse.json(
        { message: error?.message || 'Server Error' },
        { status: 500 },
      );
    }
  }),
];
EOF
